  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard onNavigate={setActiveTab} />;
      case 'pos':
        return <POS />;
      case 'orders':
        return <Orders />;
      case 'batches':
        return <Batches />;
      default:
        return <Dashboard onNavigate={setActiveTab} />;
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {renderContent()}
    </Layout>
  );
};

const App: React.FC = () => {
  return (
    <AppProvider>
      <AppContent />
    </AppProvider>
  );
};

export default App;

    const getStatusColor = () => {
        if (isFull) return {
            border: 'border-emerald-200 dark:border-emerald-900',
            bg: 'bg-emerald-50 dark:bg-emerald-900/20',
            text: 'text-emerald-700 dark:text-emerald-400',
            bar: 'bg-emerald-500',
            iconBg: 'bg-emerald-100 dark:bg-emerald-900/50',
            iconText: 'text-emerald-700 dark:text-emerald-400'
        };
        if (isOpen) return {
            border: 'border-blue-200 dark:border-blue-900',
            bg: 'bg-blue-50 dark:bg-blue-900/20',
            text: 'text-blue-700 dark:text-blue-400',
            bar: 'bg-blue-500',
            iconBg: 'bg-white dark:bg-zinc-800',
            iconText: 'text-blue-600 dark:text-blue-400'
        };
        return {
            border: 'border-slate-200 dark:border-zinc-800',
            bg: 'bg-slate-50 dark:bg-zinc-800',
            text: 'text-slate-500 dark:text-zinc-500',
            bar: 'bg-slate-400',
            iconBg: 'bg-slate-100 dark:bg-zinc-700',
            iconText: 'text-slate-500 dark:text-zinc-400'
        };
    };

    const styles = getStatusColor();

    return (
        <div className={`bg-white dark:bg-zinc-900 border ${styles.border} rounded-lg overflow-hidden transition-all relative group shadow-sm`}>
            {isFull && <div className="absolute left-0 top-0 bottom-0 w-1 bg-emerald-500 z-10 hidden md:block"></div>}

            {/* Main Row Content */}
            <div 
                className="flex flex-col md:flex-row items-stretch cursor-pointer"
                onClick={() => setExpanded(!expanded)}
            >
                {/* Status Section */}
                <div className={`p-4 md:w-64 ${styles.bg} border-b md:border-b-0 md:border-r ${styles.border} flex flex-row md:flex-col justify-between items-center md:items-start gap-3`}>
