                                    {isFull ? 'FULL' : batch.status}
                                </span>
                            </div>
                        </div>
                    </div>
                    <div className="hidden md:block">
                        <span className={`text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded ${isFull ? 'bg-emerald-200/50 dark:bg-emerald-900/50 text-emerald-800 dark:text-emerald-300' : 'bg-slate-200 dark:bg-zinc-800 text-slate-500 dark:text-zinc-500'}`}>
                            {isFull ? 'READY FOR DISPATCH' : batch.status}
                        </span>
                    </div>
                </div>

                {/* Info Section */}
                <div className="flex-1 p-4 md:p-6 flex flex-col justify-center">
