                    <div className="flex items-center gap-4 text-xs text-slate-500 dark:text-zinc-400">
                        <span className="flex items-center gap-1">
                            <Box className="w-3.5 h-3.5" /> {batchOrders.length} Orders Assigned
                        </span>
                        <span className="w-1 h-1 bg-slate-300 dark:bg-zinc-700 rounded-full"></span>
                        <span>Delivers: {new Date(batch.deliveryDate).toLocaleDateString()}</span>
                    </div>
                </div>

                {/* Capacity Section */}
                <div className={`p-4 md:p-6 md:w-72 ${styles.bg} border-t md:border-t-0 md:border-l ${styles.border} flex flex-col justify-center`}>
                    <div className="flex justify-between items-end mb-2">
                        <h4 className="text-xs font-bold text-slate-500 dark:text-zinc-500 uppercase tracking-wider">Capacity</h4>
                        <span className={`text-sm font-bold ${styles.text}`}>{batch.currentFill} / {batch.capacity}</span>
