                        ></div>
                    </div>
                    <p className="text-[10px] text-right mt-1 text-slate-400 dark:text-zinc-500 font-medium">
                        {fillPercent}% Filled
                    </p>
                </div>

                <div className={`p-2 md:p-0 md:w-16 flex items-center justify-center border-t md:border-t-0 md:border-l ${styles.border} hover:bg-slate-50 dark:hover:bg-zinc-800 transition-colors group-hover:text-emerald-600 dark:group-hover:text-emerald-400`}>
                    {expanded ? (
