                                        <tr>
                                            <th className="px-4 py-3">Order ID</th>
                                            <th className="px-4 py-3">Customer</th>
                                            <th className="px-4 py-3">Items</th>
                                            <th className="px-4 py-3 text-right">Value</th>
                                            <th className="px-4 py-3">Time</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100 dark:divide-zinc-800">
                                        {batchOrders.map(order => (
                                            <tr key={order.id} className="hover:bg-slate-50 dark:hover:bg-zinc-900 transition-colors">
                                                <td className="px-4 py-3 font-mono text-slate-700 dark:text-zinc-300">{order.id}</td>
                                                <td className="px-4 py-3 text-slate-900 dark:text-white font-medium">{order.customer.name}</td>
                                                <td className="px-4 py-3 text-slate-500 dark:text-zinc-400">{order.items.reduce((acc, i) => acc + i.quantity, 0)} items</td>
                                                <td className="px-4 py-3 text-right font-bold text-slate-900 dark:text-white">${order.totalAmount.toFixed(2)}</td>
                                                <td className="px-4 py-3 text-slate-400 dark:text-zinc-500 text-xs">
                                                    <div className="flex items-center gap-1">
                                                        <Clock className="w-3 h-3" />
