                           <input 
                               type="number"
                               min="1"
                               max="100"
                               required
                               className="w-full px-3 py-2 bg-white dark:bg-zinc-950 border border-slate-300 dark:border-zinc-700 rounded text-sm text-slate-900 dark:text-white focus:ring-1 focus:ring-emerald-500 outline-none"
                               value={newBatchData.capacity}
                               onChange={e => setNewBatchData({...newBatchData, capacity: parseInt(e.target.value)})}
                               disabled={isCreating}
                           />
                       </div>
                       <button 
                         type="submit" 
                         disabled={isCreating}
                         className="w-full py-3 bg-emerald-600 hover:bg-emerald-500 text-white font-bold rounded transition-colors mt-2 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                       >
