                           <>
                             <Loader2 className="w-4 h-4 animate-spin" />
                             Creating...
                           </>
                         ) : (
                           'Create Batch'
                         )}
                       </button>
                   </form>
               </div>
           </div>
       )}
    </div>
  );
};

