        return (names[0][0] + names[names.length - 1][0]).toUpperCase();
      }
      return agent.full_name.slice(0, 2).toUpperCase();
    }
    if (user?.email) {
      return user.email.slice(0, 2).toUpperCase();
    }
    return 'AG';
